package io.github.describeadmin.codegen.model;

import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

class ModuleSpecMutaGate1Test {

    @Test
    void nullLayoutFallsBackToNestedAndKeepsOtherComponents() {
        List<FieldSpec> fields = List.of();
        ModuleSpec nullLayout = new ModuleSpec("com.example.demo", "project", "Project",
                "biz_project", "项目", "/api/project", null, "任意来源", fields);

        // 兜底：布局为 NESTED，来源被覆盖为「默认」
        assertEquals(Layout.NESTED, nullLayout.layout());
        assertEquals("默认", nullLayout.layoutOrigin());
        assertEquals("com.example.demo.project.entity", nullLayout.packageOf("entity"));

        // 其它组件不受影响
        assertEquals("com.example.demo", nullLayout.basePackage());
        assertEquals("project", nullLayout.module());
        assertEquals("Project", nullLayout.entity());
        assertEquals("biz_project", nullLayout.table());
        assertEquals("项目", nullLayout.comment());
        assertEquals("/api/project", nullLayout.apiPrefix());
        assertSame(fields, nullLayout.fields());

        // 显式给出布局时，布局与来源原样保留
        ModuleSpec flat = new ModuleSpec("com.example.demo", "project", "Project",
                "biz_project", "项目", "/api/project", Layout.FLAT, "自定义来源", fields);
        assertEquals(Layout.FLAT, flat.layout());
        assertEquals("自定义来源", flat.layoutOrigin());
        assertEquals("com.example.demo.entity", flat.packageOf("entity"));

        // 显式 NESTED 时来源同样不被覆盖
        ModuleSpec nested = new ModuleSpec("com.example.demo", "project", "Project",
                "biz_project", "项目", "/api/project", Layout.NESTED, "自定义来源", fields);
        assertEquals("自定义来源", nested.layoutOrigin());
    }
}

